-- Errata reading for N12: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream IN ('labs','coverage')), k AS (SELECT DISTINCT patient FROM r WHERE json_extract(payload,'$.source_table')='labs' AND json_extract(payload,'$.name')='Potassium' AND coalesce(json_extract(payload,'$.result_status'),'')<>'cancelled' AND typeof(json_extract(payload,'$.value')) IN ('integer','real') AND json_extract(payload,'$.value') >= 5.0 AND json_extract(payload,'$.event_date') BETWEEN '2028-08-16' AND '2029-08-15'), c AS (SELECT patient FROM r WHERE json_extract(payload,'$.source_table')='coverage' AND json_extract(payload,'$.coverage_type')='commercial') SELECT p.id AS patient_id FROM patients p WHERE p.id IN (SELECT patient FROM k) AND p.id IN (SELECT patient FROM c) AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) BETWEEN 40 AND 64 ORDER BY 1;
